// Возвращает функцию, которая вызывает fn только в первый раз,
// а дальше отдаёт результат первого вызова
function once(fn) {
  return function (...args) {
    let called = false;
    let result;
    if (!called) {
      called = true;
      result = fn(...args);
    }
    return result;
  };
}

// Имитация кнопки «Оплатить»: clicks — сколько раз нажали
function payClicks(clicks) {
  let charges = 0;
  const pay = once(() => {
    charges += 1;
    return `order-${charges}`;
  });
  const receipts = [];
  for (let i = 0; i < clicks; i += 1) {
    receipts.push(pay());
  }
  return { charges, receipts };
}

