    (r) =>
      `<li data-rating="${escapeHtml(r.rating)}"><b>${escapeHtml(r.author)}</b>: ${escapeHtml(r.text)}</li>`
  );
  return `<ul class="reviews">${items.join('')}</ul>`;
}

