import { useEffect, useState } from 'react';

export function OrdersPage() {
  const [status, setStatus] = useState('loading');
  const [orders, setOrders] = useState([]);
  const [error, setError] = useState(null);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    setStatus('loading');
    setError(null);

    fetch('/api/orders', { signal: controller.signal })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`сервер ответил ${res.status}`);
        }
        return res.json();
      })
      .then((data) => {
        setOrders(data);
        setStatus('success');
      })
      .catch((err) => {
        if (err.name === 'AbortError') {
          return;
        }
        setError(err.message);
        setStatus('error');
      });

    return () => controller.abort();
  }, [attempt]);

  if (status === 'loading') {
    return <p role="status">Загружаем заказы…</p>;
  }

  if (status === 'error') {
    return (
      <div role="alert">
        <p>Не удалось загрузить заказы: {error}</p>
        <button type="button" onClick={() => setAttempt((n) => n + 1)}>
          Повторить
        </button>
      </div>
    );
  }

  if (orders.length === 0) {
    return (
      <p>
        У вас пока нет заказов. <a href="/catalog">Перейти в каталог</a>
      </p>
    );
  }

  return (
    <ul>
      {orders.map((order) => (
        <li key={order.id}>
          Заказ №{order.id} — {order.total} ₽
        </li>
      ))}
    </ul>
  );
}

